export function auraTotals(entries,mode,values){if(mode==='horde')return [];const counts=new Map();for(const entry of entries)if(entry.tier===4)counts.set(entry.element,(counts.get(entry.element)||0)+1);return [...counts].filter(([element])=>values[element]).map(([element,count])=>{const config=values[element],same=Math.min(config.cap,count*config.base);return {element,count,...config,same,other:same*config.otherElementMultiplier}})}
